package com.sakib.portebo.ui;
import android.os.Bundle;import android.view.Gravity;import android.view.View;import android.widget.LinearLayout;import android.widget.ProgressBar;import android.widget.ScrollView;import android.widget.TextView;import android.widget.Toast;import androidx.annotation.Nullable;import androidx.appcompat.app.AppCompatActivity;import com.google.android.material.button.MaterialButton;import com.google.android.material.card.MaterialCardView;import com.google.android.material.chip.Chip;import com.google.android.material.chip.ChipGroup;import com.sakib.portebo.R;import com.sakib.portebo.message.MessageManager;import com.sakib.portebo.util.BengaliDateFormat;import java.util.ArrayList;import java.util.List;
public class DevInboxActivity extends PaletteActivity{private LinearLayout list;private ProgressBar progress;private TextView error;private String token,filter="All";private int page=0;private List<MessageManager.MessageItem> all=new ArrayList<>();private ChipGroup chips;private MaterialButton older,newer;private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}@Override protected void onCreate(@Nullable Bundle b){super.onCreate(b);token=getSharedPreferences("dev_auth",0).getString("id_token","");build();load();}
private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(10),dp(16),dp(12));root.setBackgroundColor(getColor(R.color.bg_app));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView back=new TextView(this);back.setText("‹");back.setTextSize(32);back.setTextColor(getColor(R.color.text_primary));back.setOnClickListener(v->finish());top.addView(back,new LinearLayout.LayoutParams(dp(44),dp(48)));TextView title=new TextView(this);title.setText("ডেভেলপার ইনবক্স");title.setTextSize(19);title.setTypeface(null,1);title.setTextColor(getColor(R.color.text_primary));top.addView(title,new LinearLayout.LayoutParams(0,-2,1));MaterialButton refresh=new MaterialButton(this);refresh.setText("Refresh");refresh.setOnClickListener(v->load());top.addView(refresh);root.addView(top);chips=new ChipGroup(this);chips.setSingleSelection(true);chips.setSelectionRequired(true);String[] names={"All","Feedback","Suggestion","Issue"};for(String n:names){Chip chip=new Chip(this);chip.setText(n);chip.setCheckable(true);chip.setChecked(n.equals(filter));chip.setOnClickListener(v->{filter=n;page=0;render();});chips.addView(chip);}root.addView(chips);progress=new ProgressBar(this);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-2,-2);pp.gravity=Gravity.CENTER;root.addView(progress,pp);error=new TextView(this);error.setGravity(Gravity.CENTER);error.setTextColor(getColor(R.color.tier_blacklist));root.addView(error,new LinearLayout.LayoutParams(-1,-2));ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout pages=new LinearLayout(this);pages.setGravity(Gravity.CENTER);older=new MaterialButton(this);older.setText("See previous message");newer=new MaterialButton(this);newer.setText("See newer");older.setOnClickListener(v->{page++;render();});newer.setOnClickListener(v->{if(page>0)page--;render();});pages.addView(newer);pages.addView(older);root.addView(pages);setContentView(root);}
private void load(){if(token.isEmpty()){error.setText("আবার লগইন করো।");progress.setVisibility(View.GONE);return;}progress.setVisibility(View.VISIBLE);error.setText("");MessageManager.getDeveloperInboxAsync(this,(items,code,offline)->{progress.setVisibility(View.GONE);if(isFinishing())return;if(code!=200){error.setText(offline?"ইন্টারনেট সংযোগ নেই।":code==401?"ডেভেলপার লগইন মেয়াদ শেষ বা অনুমতি নেই। About থেকে logout করে আবার login করো।":"ইনবক্স লোড হয়নি (কোড "+(code==0?"?":code)+")");all.clear();}else{token=getSharedPreferences("dev_auth",0).getString("id_token",token);all=items;page=0;}render();});}
private List<MessageManager.MessageItem> filtered(){List<MessageManager.MessageItem> out=new ArrayList<>();for(MessageManager.MessageItem x:all)if(filter.equals("All")||filter.equalsIgnoreCase(x.category))out.add(x);return out;}private void render(){list.removeAllViews();List<MessageManager.MessageItem> data=filtered();int begin=Math.min(page*10,data.size()),end=Math.min(begin+10,data.size());for(int i=begin;i<end;i++)list.addView(messageCard(data.get(i)));if(data.isEmpty()&&error.getText().length()==0){TextView empty=new TextView(this);empty.setText("এখন কোনো মেসেজ নেই।");empty.setTextColor(getColor(R.color.text_secondary));empty.setGravity(Gravity.CENTER);list.addView(empty,new LinearLayout.LayoutParams(-1,dp(220)));}newer.setVisibility(page>0?View.VISIBLE:View.GONE);older.setVisibility(end<data.size()?View.VISIBLE:View.GONE);}
private View messageCard(MessageManager.MessageItem item){MaterialCardView card=new MaterialCardView(this);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(dp(4),dp(5),dp(34),dp(8));card.setLayoutParams(cp);card.setRadius(dp(20));card.setCardElevation(dp(2));card.setCardBackgroundColor(getColor(R.color.bg_card));LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(14),dp(12),dp(14),dp(12));card.addView(box);TextView cat=new TextView(this);String category=item.category==null?"Feedback":item.category;cat.setText(category.substring(0,1).toUpperCase(java.util.Locale.ROOT)+category.substring(1).toLowerCase(java.util.Locale.ROOT));cat.setTextColor(category.equalsIgnoreCase("issue")?getColor(R.color.tier_blacklist):category.equalsIgnoreCase("suggestion")?getColor(R.color.tier_greylist):getColor(R.color.tier_whitelist));cat.setTextSize(12);cat.setTypeface(null,1);box.addView(cat);TextView time=new TextView(this);time.setText(BengaliDateFormat.format(item.date));time.setTextColor(getColor(R.color.text_secondary));time.setTextSize(11);box.addView(time);TextView body=new TextView(this);body.setText(item.content);body.setTextColor(getColor(R.color.text_primary));body.setTextSize(14);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(7);box.addView(body,bp);if(item.hasImage){MaterialButton photo=new MaterialButton(this);photo.setText("ছবি খুলুন");photo.setIconResource(R.drawable.ic_add_photo);photo.setOnClickListener(v->{photo.setEnabled(false);photo.setText("লোড হচ্ছে…");MessageManager.getFeedbackImageAsync(this,item.id,(bytes,code,offline)->{if(isFinishing())return;photo.setEnabled(true);photo.setText("ছবি খুলুন");if(bytes==null){Toast.makeText(this,offline?"ইন্টারনেট সংযোগ নেই।":"ছবি লোড হয়নি (কোড "+(code==0?"?":code)+")",Toast.LENGTH_LONG).show();return;}android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null){Toast.makeText(this,"ছবিটি খোলা যায়নি।",Toast.LENGTH_SHORT).show();return;}android.widget.ImageView image=new android.widget.ImageView(this);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);image.setScaleType(android.widget.ImageView.ScaleType.FIT_CENTER);image.setMaxHeight(dp(520));ScrollView viewer=new ScrollView(this);viewer.addView(image,new ScrollView.LayoutParams(-1,-2));new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("সংযুক্ত ছবি").setView(viewer).setPositiveButton("বন্ধ",null).show();});});LinearLayout.LayoutParams photoLp=new LinearLayout.LayoutParams(-2,dp(40));photoLp.topMargin=dp(6);box.addView(photo,photoLp);}MaterialButton like=new MaterialButton(this);like.setText(item.liked?"Liked ✓":"Like");like.setEnabled(!item.liked);like.setOnClickListener(v->{like.setEnabled(false);MessageManager.getFreshDevToken(this,(authOk,freshToken)->{if(!authOk){like.setEnabled(true);Toast.makeText(this,freshToken,Toast.LENGTH_LONG).show();return;}token=freshToken;MessageManager.likeMessage(item.id,item.senderId,item.category,item.content,freshToken,(ok,msg)->{if(ok){item.liked=true;like.setText("Liked ✓");}else like.setEnabled(true);Toast.makeText(this,msg,Toast.LENGTH_SHORT).show();});});});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(40));lp.topMargin=dp(6);box.addView(like,lp);return card;}}
